sourceBlocks.zero_v3:
MINLINE void zero_v3(float r[3])
{
  r[0] = 0.0f;
  r[1] = 0.0f;
  r[2] = 0.0f;
}

sourceBlocks.copy_v3_v3:
MINLINE void copy_v3_v3(float r[3], const float a[3])
{
  r[0] = a[0];
  r[1] = a[1];
  r[2] = a[2];
}

sourceBlocks.sub_v3_v3v3:
MINLINE void sub_v3_v3v3(float r[3], const float a[3], const float b[3])
{
  r[0] = a[0] - b[0];
  r[1] = a[1] - b[1];
  r[2] = a[2] - b[2];
}

sourceBlocks.mul_v3_v3fl:
MINLINE void mul_v3_v3fl(float r[3], const float a[3], float f)
{
  r[0] = a[0] * f;
  r[1] = a[1] * f;
  r[2] = a[2] * f;
}

sourceBlocks.dot_v3v3:
MINLINE float dot_v3v3(const float a[3], const float b[3])
{
  return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
}

sourceBlocks.normalize_v3_v3_length:
MINLINE float normalize_v3_v3_length(float r[3], const float a[3], const float unit_length)
{
  float d = dot_v3v3(a, a);

  /* A larger value causes normalize errors in a scaled down models with camera extreme close. */
  if (d > 1.0e-35f) {
    d = sqrtf(d);
    mul_v3_v3fl(r, a, unit_length / d);
  }
  else {
    /* Either the vector is small or one of it's values contained `nan`. */
    zero_v3(r);
    d = 0.0f;
  }

  return d;
}

sourceBlocks.normalize_v3_v3:
MINLINE float normalize_v3_v3(float r[3], const float a[3])
{
  return normalize_v3_v3_length(r, a, 1.0f);
}

sourceBlocks.normalize_v3:
MINLINE float normalize_v3(float n[3])
{
  return normalize_v3_v3(n, n);
}

